-- ----------------------------
-- Event structure for limpiar_carritos_inactivos
-- ----------------------------
DROP EVENT IF EXISTS `limpiar_carritos_inactivos`;
delimiter ;;
CREATE EVENT `limpiar_carritos_inactivos`
ON SCHEDULE
EVERY '1' DAY STARTS '2026-08-08 02:00:00'
ON COMPLETION PRESERVE
DO DELETE FROM carrito_items WHERE updated_at < NOW() - INTERVAL 7 DAY
;;
delimiter ;

SET FOREIGN_KEY_CHECKS = 1;
